import { ok, fail } from './result.js';
import { roundCents } from './money.js';
import { getCustomer, normalizeId, TIER_DISCOUNTS } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { isValidDate, addDays } from './dates.js';

function isValidDiscount(discountPercent) {
  return typeof discountPercent === 'number' && discountPercent >= 0 && discountPercent <= 100;
}

function calculateDueDate(issueDate, terms) {
  if (terms === 'NET14') return addDays(issueDate, 14);
  if (terms === 'NET30') return addDays(issueDate, 30);
  if (terms === 'EOM') {
    const date = new Date(issueDate + 'T00:00:00Z');
    const lastDay = new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth() + 1, 0));
    return lastDay.toISOString().slice(0, 10);
  }
  return null;
}

/**
 * Create an invoice with the given customer, date, and line items.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }>, terms?: string }}
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array, terms?: string, dueDate?: string } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms }) {
  const normalizedCustomerId = normalizeId(customerId);
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;
  const customer = customerResult.value;

  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  const finalTerms = terms ?? 'NET30';
  if (!['NET14', 'NET30', 'EOM'].includes(finalTerms)) {
    return fail('TERMS_INVALID');
  }
  const dueDate = calculateDueDate(issueDate, finalTerms);

  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  const invoiceLines = [];
  for (const line of lines) {
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    if (line.discountPercent !== undefined && !isValidDiscount(line.discountPercent)) {
      return fail('DISCOUNT_INVALID');
    }

    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    const invoiceLine = {
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };

    if (line.discountPercent !== undefined) {
      invoiceLine.discountPercent = line.discountPercent;
    } else {
      const tierDiscount = TIER_DISCOUNTS[customer.tier] ?? 0;
      if (tierDiscount > 0) {
        invoiceLine.discountPercent = tierDiscount;
      }
    }

    invoiceLines.push(invoiceLine);
  }

  const invoice = {
    customerId: normalizedCustomerId,
    issueDate,
    status: 'draft',
    lines: invoiceLines,
  };

  if (finalTerms !== 'NET30') {
    invoice.terms = finalTerms;
  }
  invoice.dueDate = dueDate;

  return ok(invoice);
}

/**
 * Calculate the total amount for a line item (qty × unitPrice).
 * @param {{ qty: number, unitPrice: number }}
 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
 */
export function lineTotal(line) {
  if (!line || !Number.isInteger(line.qty) || line.qty <= 0) {
    return fail('LINE_INVALID');
  }
  if (typeof line.unitPrice !== 'number' || line.unitPrice < 0) {
    return fail('LINE_INVALID');
  }
  return ok(line.qty * line.unitPrice);
}

/**
 * Calculate the discount amount for a line item.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }}
 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
 */
export function lineDiscount(line) {
  const totalResult = lineTotal(line);
  if (!totalResult.ok) return totalResult;

  if (!line.discountPercent) {
    return ok(0);
  }

  if (!isValidDiscount(line.discountPercent)) {
    return fail('DISCOUNT_INVALID');
  }

  const discount = roundCents(totalResult.value * line.discountPercent / 100);
  return ok(Math.max(0, discount));
}

/**
 * Calculate the VAT amount for a line item.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }}
 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
 */
export function lineVat(line) {
  const totalResult = lineTotal(line);
  if (!totalResult.ok) return totalResult;

  const discountResult = lineDiscount(line);
  if (!discountResult.ok) return discountResult;

  const amountAfterDiscount = totalResult.value - discountResult.value;
  if (typeof line.vatRate !== 'number' || line.vatRate < 0) {
    return fail('LINE_INVALID');
  }

  const vat = roundCents(amountAfterDiscount * line.vatRate / 100);
  return ok(Math.max(0, vat));
}

/**
 * Calculate totals for an invoice: subtotal, discount, VAT, and total.
 * @param {{ lines: Array }}
 * @returns {{ ok: true, value: { subtotal: number, discount: number, vat: number, total: number } } | { ok: false, error: string }}
 */
export function invoiceTotals(invoice) {
  if (!invoice || !Array.isArray(invoice.lines)) {
    return fail('INVOICE_INVALID');
  }

  let subtotal = 0;
  let discount = 0;
  let vat = 0;

  for (const line of invoice.lines) {
    const totalResult = lineTotal(line);
    if (!totalResult.ok) return totalResult;
    subtotal += totalResult.value;

    const discountResult = lineDiscount(line);
    if (!discountResult.ok) return discountResult;
    discount += discountResult.value;

    const vatResult = lineVat(line);
    if (!vatResult.ok) return vatResult;
    vat += vatResult.value;
  }

  const total = Math.max(0, subtotal - discount + vat);

  return ok({ subtotal, discount, vat, total });
}

/**
 * Add or update a line on a draft invoice.
 * If the SKU already exists, increase its quantity; otherwise add a new line.
 * @param {{ status: string, lines: Array }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }}
 * @returns {{ ok: true, value: { status: string, lines: Array } } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  if (!invoice || invoice.status !== 'draft') return fail('NOT_DRAFT');

  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  if (discountPercent !== undefined && !isValidDiscount(discountPercent)) {
    return fail('DISCOUNT_INVALID');
  }

  const customerResult = getCustomer(invoice.customerId);
  if (!customerResult.ok) return customerResult;
  const customer = customerResult.value;

  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;
  const newLines = invoice.lines.map((line) => ({ ...line }));

  const existingIndex = newLines.findIndex((line) => line.sku === sku);
  if (existingIndex >= 0) {
    newLines[existingIndex] = { ...newLines[existingIndex], qty: newLines[existingIndex].qty + qty };
    if (discountPercent !== undefined) {
      newLines[existingIndex].discountPercent = discountPercent;
    }
  } else {
    const newLine = {
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };
    if (discountPercent !== undefined) {
      newLine.discountPercent = discountPercent;
    } else {
      const tierDiscount = TIER_DISCOUNTS[customer.tier] ?? 0;
      if (tierDiscount > 0) {
        newLine.discountPercent = tierDiscount;
      }
    }
    newLines.push(newLine);
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from a draft invoice.
 * @param {{ status: string, lines: Array }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: { status: string, lines: Array } } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  if (!invoice || invoice.status !== 'draft') return fail('NOT_DRAFT');

  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex < 0) return fail('LINE_NOT_FOUND');

  if (invoice.lines.length === 1) return fail('NO_LINES');

  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue a draft invoice, assigning it a number and changing status to 'issued'.
 * @param {{ status: string, issueDate: string, lines: Array }} invoice
 * @param {Array<string>} existingNumbers
 * @returns {{ ok: true, value: { number: string, status: string } } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (!invoice || invoice.status !== 'draft') return fail('NOT_DRAFT');

