  assert.deepEqual(result, { ok: false, error: 'TERMS_INVALID' });
});

test('createInvoice: case sensitive terms validation', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'net30',
  });

  assert.deepEqual(result, { ok: false, error: 'TERMS_INVALID' });
});

test('createInvoice: happy path with multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-003', // Silver tier (2.5%)
    issueDate: '2025-01-20',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
