    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.deepEqual(result, {
    ok: true,
    value: {
      customerId: 'C-001',
      issueDate: '2024-10-15',
      status: 'draft',
      lines: [
        {
          sku: 'DEV-HOUR',
          name: 'Development (hour)',
          qty: 10,
          unitPrice: 9500,
          vatRate: 21,
          discountPercent: 5,
        },
      ],
      dueDate: '2024-11-14',
    },
  });
});

