test('invoiceTotals: happy path with single line', () => {
  const result = createInvoice({
    customerId: 'C-001', // Gold tier (5%)
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }], // 10 * 9500 = 95000, discount 5%, VAT 21%
  });

  const totals = invoiceTotals(result.value);

  // Subtotal: 95000
  // Discount: 4750 (5% of 95000)
  // Amount after discount: 90250
  // VAT: 18952.5 → 18952 (21% of 90250, banker's rounding)
  // Total: 90250 + 18952 = 109202

  assert.deepEqual(totals, {
    ok: true,
    value: { subtotal: 95000, discount: 4750, vat: 18952, total: 109202 },
  });
});

test('invoiceTotals: happy path with multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-001', // Gold tier (5%)
    issueDate: '2024-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 5 }, // 5 * 8500 = 42500, discount 2125, after 40375, VAT 8478.75 → 8479
      { sku: 'DEV-HOUR', qty: 10 }, // 10 * 9500 = 95000, discount 4750, after 90250, VAT 18952.5 → 18952
      { sku: 'COPY-HOUR', qty: 3 }, // 3 * 6000 = 18000, discount 900, after 17100, VAT 3591
    ],
  });

  const totals = invoiceTotals(result.value);

  assert.equal(totals.ok, true);
  assert.equal(totals.value.subtotal, 155500);
  assert.equal(totals.value.discount, 7775);
  assert.equal(totals.value.vat, 31022); // 8479 + 18952 + 3591
  assert.equal(totals.value.total, 178747); // 155500 - 7775 + 31022
});

test('invoiceTotals: total with VAT and no discount', () => {
  const result = createInvoice({
