test('addLine: add to invoice with multiple existing lines', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 3 },
    ],
  });

  const result = addLine(invoiceResult.value, { sku: 'COPY-HOUR', qty: 2 });

