test('different tiers apply different discounts', () => {
  const gold = createInvoice({
    customerId: 'C-001', // Gold
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  });

  const silver = createInvoice({
    customerId: 'C-003', // Silver
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  });

  const standard = createInvoice({
    customerId: 'C-002', // Standard
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  });

  const goldTotals = invoiceTotals(gold.value);
  const silverTotals = invoiceTotals(silver.value);
  const standardTotals = invoiceTotals(standard.value);

  assert.equal(goldTotals.value.discount, 47500); // 5% of 950000
  assert.equal(silverTotals.value.discount, 23750); // 2.5% of 950000
  assert.equal(standardTotals.value.discount, 0); // No discount
});

test('applyVoucher: happy path', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const result = applyVoucher(invoiceResult.value, { code: 'SAVE50', amount: 5000 });

  assert.equal(result.ok, true);
  assert.deepEqual(result.value.voucher, { code: 'SAVE50', amount: 5000 });
});

test('applyVoucher: voucher deducted from total', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const voucherResult = applyVoucher(invoiceResult.value, { code: 'DISCOUNT10', amount: 10000 });
  const totals = invoiceTotals(voucherResult.value);

  // Original total would be 114950 (95000 - 4750 discount + 19950 VAT)
  // With 10000 voucher: 114950 - 10000 = 104950
  assert.equal(totals.value.voucher, 10000);
  assert.equal(totals.value.total, 104950);
});

