  applyVoucher(invoiceResult.value, { code: 'SAVE50', amount: 5000 });

  assert.deepEqual(invoiceResult.value, original);
  assert.equal(invoiceResult.value.voucher, undefined);
});

test('applyVoucher: voucher amount can be large', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const result = applyVoucher(invoiceResult.value, { code: 'HUGE', amount: 999999999 });

  assert.equal(result.ok, true);
  assert.equal(result.value.voucher.amount, 999999999);
});

test('invoiceTotals: includes voucher field', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const totals = invoiceTotals(invoiceResult.value);

  assert.equal(totals.value.voucher, 0);
});

test('invoiceTotals: voucher reduces total', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const withVoucher = applyVoucher(invoiceResult.value, { code: 'SAVE25', amount: 25000 });
  const totals = invoiceTotals(withVoucher.value);

  // Subtotal: 95000 - 4750 discount + 19950 VAT = 114950 - 25000 = 89950
  assert.equal(totals.value.total, 89950);
});

test('invoiceTotals: voucher clamped at zero', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  // Total is 114950, but apply voucher for more than that
  const withVoucher = applyVoucher(invoiceResult.value, { code: 'HUGE', amount: 200000 });
  const totals = invoiceTotals(withVoucher.value);

  // Should not go below 0
  assert.equal(totals.value.total, 0);
});

