import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, lineDiscount, lineVat, invoiceTotals, addLine, removeLine, applyVoucher, issueInvoice } from '../src/invoices.js';

test('createInvoice: happy path with single line', () => {
  const result = createInvoice({
    customerId: 'C-001', // Gold tier (5%)
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.deepEqual(result, {
    ok: true,
    value: {
      customerId: 'C-001',
      issueDate: '2024-10-15',
      status: 'draft',
      lines: [
        {
          sku: 'DEV-HOUR',
          name: 'Development (hour)',
          qty: 10,
          unitPrice: 9500,
          vatRate: 21,
          discountPercent: 5,
        },
      ],
      dueDate: '2024-11-14',
    },
  });
});

test('createInvoice: normalizes customerId with lowercase', () => {
  const result = createInvoice({
    customerId: 'c-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
});

test('createInvoice: normalizes customerId with spaces', () => {
  const result = createInvoice({
    customerId: ' c-001 ',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
});

test('createInvoice: normalizes mixed case and spaces', () => {
  const result = createInvoice({
    customerId: ' C-007 ',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-007');
});

test('createInvoice: default terms is NET30', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(result.ok, true);
  // NET30 is the default, so it shouldn't be stored
  assert.equal(result.value.terms, undefined);
  // Due date should be 30 days after issue date
  assert.equal(result.value.dueDate, '2024-11-14');
});

test('createInvoice: NET14 terms', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'NET14',
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.terms, 'NET14');
  // Due date should be 14 days after issue date
  assert.equal(result.value.dueDate, '2024-10-29');
});

test('createInvoice: NET30 terms explicit', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'NET30',
  });

  assert.equal(result.ok, true);
  // NET30 is default, so terms shouldn't be stored
  assert.equal(result.value.terms, undefined);
  assert.equal(result.value.dueDate, '2024-11-14');
});

test('createInvoice: EOM terms', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'EOM',
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.terms, 'EOM');
  // Due date should be the last day of October (issue date's month)
  assert.equal(result.value.dueDate, '2024-10-31');
});

test('createInvoice: EOM on first day of month', () => {
  const result = createInvoice({
